PRAGMA foreign_keys = ON;
CREATE TABLE accounts (id TEXT PRIMARY KEY, username TEXT NOT NULL, name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('demo','live')), status TEXT NOT NULL DEFAULT 'connected', avatar_url TEXT, token TEXT, token_expires_at INTEGER, last_sync_at INTEGER, next_send_at INTEGER NOT NULL DEFAULT 0, permissions TEXT NOT NULL DEFAULT '[]', sync_error TEXT);
CREATE TABLE media (id TEXT NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), caption TEXT NOT NULL, type TEXT NOT NULL, permalink TEXT, thumbnail_url TEXT, published_at INTEGER NOT NULL, reach INTEGER, likes INTEGER, comments INTEGER, shares INTEGER, saves INTEGER, PRIMARY KEY(account_id,id));
CREATE INDEX media_publication ON media(account_id,published_at);
CREATE TABLE campaigns (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', draft TEXT NOT NULL, live_version_id TEXT, bound_media_id TEXT, armed_at INTEGER, baseline TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX campaigns_account ON campaigns(account_id,status);
CREATE TABLE versions (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id), input TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE contacts (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), instagram_id TEXT NOT NULL, username TEXT NOT NULL, fields TEXT NOT NULL DEFAULT '{}', tags TEXT NOT NULL DEFAULT '[]', last_interaction_at INTEGER, created_at INTEGER NOT NULL, UNIQUE(account_id,instagram_id));
CREATE TABLE events (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), payload TEXT NOT NULL, received_at INTEGER NOT NULL, applied_at INTEGER);
CREATE TABLE outbox (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), state TEXT NOT NULL DEFAULT 'pending', available_at INTEGER NOT NULL, lease_until INTEGER, attempts INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE INDEX outbox_ready ON outbox(state,available_at);
CREATE TABLE runs (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), contact_id TEXT NOT NULL REFERENCES contacts(id), campaign_id TEXT NOT NULL REFERENCES campaigns(id), version_id TEXT NOT NULL REFERENCES versions(id), comment_id TEXT NOT NULL, media_id TEXT NOT NULL, node_id TEXT, state TEXT NOT NULL, wake_at INTEGER, comment_at INTEGER NOT NULL, private_sent INTEGER NOT NULL DEFAULT 0, lock_until INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(account_id,comment_id));
CREATE INDEX runs_active ON runs(state,wake_at);
CREATE INDEX runs_contact ON runs(account_id,contact_id,created_at);
CREATE TABLE actions (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), run_id TEXT NOT NULL REFERENCES runs(id), node_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', text TEXT NOT NULL, buttons TEXT NOT NULL DEFAULT '[]', payload TEXT, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, provider_id TEXT, available_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(run_id,node_id,kind));
CREATE INDEX actions_status ON actions(status,available_at);
CREATE TABLE messages (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), contact_id TEXT NOT NULL REFERENCES contacts(id), run_id TEXT REFERENCES runs(id), direction TEXT NOT NULL, channel TEXT NOT NULL, text TEXT NOT NULL, buttons TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX messages_account ON messages(account_id,created_at);
CREATE TABLE response_tokens (token TEXT PRIMARY KEY, account_id TEXT NOT NULL, contact_id TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES runs(id), node_id TEXT NOT NULL, next_node_id TEXT NOT NULL, choice INTEGER NOT NULL, used_at INTEGER, UNIQUE(run_id,node_id,choice));
CREATE TABLE links (token TEXT PRIMARY KEY, account_id TEXT NOT NULL, campaign_id TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES runs(id), contact_id TEXT NOT NULL, action_id TEXT NOT NULL REFERENCES actions(id), destination TEXT NOT NULL, choice INTEGER NOT NULL, UNIQUE(action_id,choice));
CREATE TABLE clicks (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, campaign_id TEXT NOT NULL, run_id TEXT NOT NULL, contact_id TEXT NOT NULL, link_id TEXT NOT NULL REFERENCES links(token), automated INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX clicks_account ON clicks(account_id,created_at);
CREATE TABLE metric_snapshots (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, media_id TEXT NOT NULL, metrics TEXT NOT NULL, collected_at INTEGER NOT NULL);
CREATE TABLE responses (event_id TEXT PRIMARY KEY REFERENCES events(id), account_id TEXT NOT NULL, contact_id TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES runs(id), created_at INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE oauth_states (nonce TEXT PRIMARY KEY, session_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE demo_requests (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, action_id TEXT NOT NULL, request TEXT NOT NULL, outcome TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
